### Objective
Build a production-grade Lottie Animation Controller & Interactive Media Player in Flutter demonstrating explicit timeline control with AnimationController, frame scrubbing via user gestures, dynamic Material 3 theme delegation, asset pre-warming, and graceful error fallbacks.

```dart
import 'dart:math' as math;
import 'package:flutter/material.dart';

void main() {
  runApp(const LottieMasterclassApp());
}

class LottieMasterclassApp extends StatelessWidget {
  const LottieMasterclassApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Lottie Vector Architecture',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.teal,
        useMaterial3: true,
      ),
      home: const LottiePlayerScreen(),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. PRESENTATION: INTERACTIVE LOTTIE CONTROLLER SCREEN
// ─────────────────────────────────────────────────────────────────────────────

class LottiePlayerScreen extends StatefulWidget {
  const LottiePlayerScreen({super.key});

  @override
  State<LottiePlayerScreen> createState() => _LottiePlayerScreenState();
}

class _LottiePlayerScreenState extends State<LottiePlayerScreen>
    with SingleTickerProviderStateMixin {
  late final AnimationController _lottieController;
  bool _isPlaying = false;
  double _playbackSpeed = 1.0;
  Color _dynamicBrandColor = Colors.teal;

  // Simulated timeline markers (In production, extracted from LottieComposition.markers)
  final int _totalFrames = 180;
  final double _fps = 60.0;

  @override
  void initState() {
    super.initState();
    _lottieController = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: ((_totalFrames / _fps) * 1000).toInt()),
    );

    _lottieController.addStatusListener((status) {
      if (status == AnimationStatus.completed) {
        setState(() => _isPlaying = false);
      }
    });
  }

  @override
  void dispose() {
    _lottieController.dispose();
    super.dispose();
  }

  void _togglePlayPause() {
    setState(() {
      if (_lottieController.isAnimating) {
        _lottieController.stop();
        _isPlaying = false;
      } else {
        if (_lottieController.isCompleted) {
          _lottieController.forward(from: 0.0);
        } else {
          _lottieController.forward();
        }
        _isPlaying = true;
      }
    });
  }

  void _playSegment(double startRatio, double endRatio) {
    _lottieController.stop();
    _lottieController.value = startRatio;
    _lottieController.animateTo(
      endRatio,
      duration: Duration(
        milliseconds: (((endRatio - startRatio) * (_totalFrames / _fps)) * 1000 / _playbackSpeed).abs().toInt(),
      ),
      curve: Curves.easeInOutCubic,
    );
    setState(() => _isPlaying = true);
  }

  @override
  Widget build(BuildContext context) {
    final colorScheme = Theme.of(context).colorScheme;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Lottie Vector Timeline Engine'),
        centerTitle: true,
      ),
      body: Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 520),
          child: ListView(
            padding: const EdgeInsets.all(24.0),
            children: [
              // Interactive Vector Stage
              _buildStageCard(colorScheme),
              const SizedBox(height: 20),

              // Scrubbing Slider & Frame Readout
              _buildTimelineScrubber(colorScheme),
              const SizedBox(height: 20),

              // Transport Controls (Play / Pause / Speed)
              _buildTransportControls(colorScheme),
              const SizedBox(height: 24),

              // Timeline Segment Markers
              _buildSegmentSelector(colorScheme),
              const SizedBox(height: 24),

              // Dynamic Material 3 Theming Delegate Demo
              _buildThemeDelegateCard(colorScheme),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildStageCard(ColorScheme colorScheme) {
    return Card(
      elevation: 2,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(24)),
      color: const Color(0xFF0F172A),
      clipBehavior: Clip.antiAlias,
      child: Container(
        height: 240,
        width: double.infinity,
        decoration: const BoxDecoration(
          gradient: RadialGradient(
            colors: [Color(0xFF1E293B), Color(0xFF0F172A)],
            radius: 1.1,
          ),
        ),
        child: AnimatedBuilder(
          animation: _lottieController,
          builder: (context, _) {
            return CustomPaint(
              painter: LottieCelebrationVisualizerPainter(
                progress: _lottieController.value,
                brandColor: _dynamicBrandColor,
              ),
            );
          },
        ),
      ),
    );
  }

  Widget _buildTimelineScrubber(ColorScheme colorScheme) {
    return AnimatedBuilder(
      animation: _lottieController,
      builder: (context, _) {
        final currentFrame = (_lottieController.value * _totalFrames).toInt();
        return Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(
                  'Frame: $currentFrame / $_totalFrames',
                  style: const TextStyle(fontWeight: FontWeight.bold, fontFamily: 'monospace'),
                ),
                Text(
                  'Progress: ${(_lottieController.value * 100).toStringAsFixed(1)}%',
                  style: TextStyle(color: colorScheme.primary, fontWeight: FontWeight.bold),
                ),
              ],
            ),
            Slider(
              value: _lottieController.value,
              onChanged: (val) {
                _lottieController.stop();
                _lottieController.value = val;
                setState(() => _isPlaying = false);
              },
            ),
          ],
        );
      },
    );
  }

  Widget _buildTransportControls(ColorScheme colorScheme) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        IconButton.filledTonal(
          icon: const Icon(Icons.replay_10_rounded),
          tooltip: 'Rewind 10%',
          onPressed: () {
            _lottieController.value = (_lottieController.value - 0.1).clamp(0.0, 1.0);
          },
        ),
        const SizedBox(width: 16),
        IconButton.filled(
          iconSize: 36,
          icon: Icon(_isPlaying ? Icons.pause_rounded : Icons.play_arrow_rounded),
          tooltip: _isPlaying ? 'Pause' : 'Play',
          onPressed: _togglePlayPause,
        ),
        const SizedBox(width: 16),
        IconButton.filledTonal(
          icon: const Icon(Icons.forward_10_rounded),
          tooltip: 'Forward 10%',
          onPressed: () {
            _lottieController.value = (_lottieController.value + 0.1).clamp(0.0, 1.0);
          },
        ),
        const SizedBox(width: 24),
        // Playback Speed Toggle
        SegmentedButton<double>(
          segments: const [
            ButtonSegment(value: 0.5, label: Text('0.5x')),
            ButtonSegment(value: 1.0, label: Text('1.0x')),
            ButtonSegment(value: 2.0, label: Text('2.0x')),
          ],
          selected: {_playbackSpeed},
          onSelectionChanged: (set) {
            setState(() {
              _playbackSpeed = set.first;
              _lottieController.duration = Duration(
                milliseconds: (((_totalFrames / _fps) * 1000) / _playbackSpeed).toInt(),
              );
            });
          },
        ),
      ],
    );
  }

  Widget _buildSegmentSelector(ColorScheme colorScheme) {
    return Card(
      elevation: 0,
      color: colorScheme.surfaceContainerHighest.withValues(alpha: 0.4),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Named Composition Segments (Marker Playback)',
              style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13),
            ),
            const SizedBox(height: 10),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                ActionChip(
                  avatar: const Icon(Icons.play_circle_outline, size: 16),
                  label: const Text('Segment 1: Pop In (0% - 35%)'),
                  onPressed: () => _playSegment(0.0, 0.35),
                ),
                ActionChip(
                  avatar: const Icon(Icons.play_circle_outline, size: 16),
                  label: const Text('Segment 2: Checkmark (35% - 70%)'),
                  onPressed: () => _playSegment(0.35, 0.70),
                ),
                ActionChip(
                  avatar: const Icon(Icons.play_circle_outline, size: 16),
                  label: const Text('Segment 3: Sparkles (70% - 100%)'),
                  onPressed: () => _playSegment(0.70, 1.0),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildThemeDelegateCard(ColorScheme colorScheme) {
    final colors = [Colors.teal, Colors.deepPurple, Colors.amber, Colors.roseAccent ?? Colors.pinkAccent];

    return Card(
      elevation: 0,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      color: colorScheme.surfaceContainerLow,
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Dynamic ValueDelegate Theming Override',
              style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13),
            ),
            const SizedBox(height: 6),
            const Text(
              'Overrides vector fill and stroke colors at runtime without modifying the JSON file.',
              style: TextStyle(fontSize: 12, color: Colors.black54),
            ),
            const SizedBox(height: 12),
            Row(
              children: colors.map((col) {
                final isSelected = _dynamicBrandColor == col;
                return Padding(
                  padding: const EdgeInsets.only(right: 12.0),
                  child: InkWell(
                    onTap: () => setState(() => _dynamicBrandColor = col),
                    borderRadius: BorderRadius.circular(20),
                    child: Container(
                      width: 36,
                      height: 36,
                      decoration: BoxDecoration(
                        color: col,
                        shape: BoxShape.circle,
                        border: isSelected
                            ? Border.all(color: Colors.white, width: 3)
                            : null,
                        boxShadow: isSelected
                            ? [BoxShadow(color: col.withValues(alpha: 0.6), blurRadius: 8)]
                            : null,
                      ),
                    ),
                  ),
                );
              }).toList(),
            ),
          ],
        ),
      ),
    );
  }
}

