// 2. PROCEDURAL LOTTIE CELEBRATION PAINTER
// Simulates the path-morphing & keyframe rendering of package:lottie
// ─────────────────────────────────────────────────────────────────────────────

class LottieCelebrationVisualizerPainter extends CustomPainter {
  final double progress;
  final Color brandColor;

  LottieCelebrationVisualizerPainter({
    required this.progress,
    required this.brandColor,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height / 2);

    // 1. Stage 1 (0.0 -> 0.35): Expanding Circular Badge with Bounce
    final badgeProgress = (progress / 0.35).clamp(0.0, 1.0);
    final badgeScale = Curves.elasticOut.transform(badgeProgress);
    final badgeRadius = 46.0 * badgeScale;

    if (badgeRadius > 0) {
      final badgePaint = Paint()
        ..color = brandColor
        ..style = PaintingStyle.fill;
      canvas.drawCircle(center, badgeRadius, badgePaint);
    }

    // 2. Stage 2 (0.35 -> 0.70): Trim Path Vector Checkmark
    if (progress >= 0.35) {
      final checkProgress = ((progress - 0.35) / 0.35).clamp(0.0, 1.0);
      final strokePaint = Paint()
        ..color = Colors.white
        ..style = PaintingStyle.stroke
        ..strokeWidth = 6.0
        ..strokeCap = StrokeCap.round;

      final checkPath = Path();
      final p1 = Offset(center.dx - 18, center.dy);
      final p2 = Offset(center.dx - 4, center.dy + 14);
      final p3 = Offset(center.dx + 20, center.dy - 12);

      if (checkProgress < 0.4) {
        // Drawing first tick leg
        final t = checkProgress / 0.4;
        checkPath.moveTo(p1.dx, p1.dy);
        checkPath.lineTo(p1.dx + (p2.dx - p1.dx) * t, p1.dy + (p2.dy - p1.dy) * t);
      } else {
        // Drawing full first leg + progressive second leg
        checkPath.moveTo(p1.dx, p1.dy);
        checkPath.lineTo(p2.dx, p2.dy);
        final t = (checkProgress - 0.4) / 0.6;
        checkPath.lineTo(p2.dx + (p3.dx - p2.dx) * t, p2.dy + (p3.dy - p2.dy) * t);
      }
      canvas.drawPath(checkPath, strokePaint);
    }

    // 3. Stage 3 (0.70 -> 1.0): Radial Particle Burst
    if (progress >= 0.70) {
      final burstProgress = ((progress - 0.70) / 0.30).clamp(0.0, 1.0);
      final particleDistance = 58.0 + (burstProgress * 30.0);
      final particleAlpha = (1.0 - burstProgress).clamp(0.0, 1.0);

      const particleCount = 8;
      for (int i = 0; i < particleCount; i++) {
        final angle = (i * 2 * math.pi / particleCount) + (burstProgress * 0.4);
        final pOffset = Offset(
          center.dx + math.cos(angle) * particleDistance,
          center.dy + math.sin(angle) * particleDistance,
        );
        final pPaint = Paint()
          ..color = brandColor.withValues(alpha: particleAlpha)
          ..style = PaintingStyle.fill;
        canvas.drawCircle(pOffset, 4.0 * (1.0 - burstProgress * 0.5), pPaint);
      }
    }
  }

  @override
  bool shouldRepaint(covariant LottieCelebrationVisualizerPainter oldDelegate) {
    return oldDelegate.progress != progress || oldDelegate.brandColor != brandColor;
  }
}
```

### Step-by-Step Code Walkthrough

1. **Explicit AnimationController Binding**:
   `_lottieController` manages timeline progression. Rather than relying on implicit loops, its duration is synchronized with the composition duration (`_totalFrames / _fps`), giving the developer absolute control over current progress.
2. **Interactive Frame Scrubbing**:
   The `Slider` widget reads `_lottieController.value` and allows learners to drag backwards and forwards across frames, demonstrating how Lottie recalculates vector paths at fractional timestamps.
3. **Named Segment & Marker Playback**:
   `_playSegment(start, end)` demonstrates playing bounded animation intervals (e.g. Pop In vs Checkmark vs Burst), identical to calling `_controller.animateTo(endFrame / totalFrames)` in production.
4. **Dynamic Theme Delegation (`ValueDelegate`)**:
   Changing `_dynamicBrandColor` instantly repaints the vector fills. In `package:lottie`, this maps to `ValueDelegate.color(['Layer', 'Group', 'Fill'], value: primaryColor)`.
